19	    static byte[] readAllBytes(InputStream is) throws Exception {
20	        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
21	        byte[] data = new byte[4096];
22	        int bytesRead;
23	        while ((bytesRead = is.read(data, 0, data.length)) != -1) {
24	            buffer.write(data, 0, bytesRead);
25	        }
26	        return buffer.toByteArray();
27	    }
28	
29	    static void executeSql(Connection conn, String resourcePath, Class<?> clazz) {
30	        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath);
31	             Statement stmt = conn.createStatement()) {
32	            String sql = new String(readAllBytes(is), StandardCharsets.UTF_8);
33	            StringBuilder cleaned = new StringBuilder();
34	            for (String rawLine : sql.split("\n")) {
35	                String line = rawLine.trim();
36	                if (line.startsWith("--") || line.isEmpty()) continue;
37	                cleaned.append(line).append(" ");
38	            }
39	            for (String statement : cleaned.toString().split(";")) {
40	                String trimmed = statement.trim();
41	                if (!trimmed.isEmpty()) stmt.execute(trimmed);
42	            }
43	        } catch (Exception e) {
44	            throw new RuntimeException("SQL execution failed: " + resourcePath, e);
45	        }
46	    }
