48	    static String readResource(String resourcePath, Class<?> clazz) {
49	        try (InputStream is = clazz.getClassLoader().getResourceAsStream(resourcePath)) {
50	            return new String(readAllBytes(is), StandardCharsets.UTF_8);
51	        } catch (Exception e) {
52	            throw new RuntimeException("Resource read failed: " + resourcePath, e);
53	        }
54	    }
