56	    /**
57	     * 관리자 로그인 세션을 획득하여 SESSION 쿠키를 반환한다.
58	     * 1단계: POST /web/login/ajax (id, pw) → accountSeq 반환
59	     * 2단계: JDBC로 ACCOUNT_SMS에서 인증번호 조회
60	     * 3단계: POST /web/login/sms (accountSeq, certificationNo) → 세션 생성
61	     * 3-B단계: 약관 동의가 필요하면 POST /web/login/agreeTerms 호출
62	     * 4단계: tokenErr="001"이면 POST /web/login/token 호출하여 loginToken 발급
63	     *
64	     * @param baseUrl 서버 URL (예: http://localhost:8080)
65	     * @param id 관리자 ID
66	     * @param pw 관리자 비밀번호
67	     * @param conn DB 연결
68	     * @return SESSION 쿠키 값
69	     */
70	    static String adminLogin(String baseUrl, String id, String pw, Connection conn) {
71	        // 1단계: 로그인 시도 → SMS 인증번호 발송 + accountSeq 반환
72	        io.restassured.response.Response loginResp = io.restassured.RestAssured.given()
73	            .baseUri(baseUrl)
74	            .header("X-Requested-With", "XMLHttpRequest")
75	            .contentType("application/x-www-form-urlencoded")
76	            .formParam("id", id)
77	            .formParam("pw", pw)
78	        .when()
79	            .post("/web/login/ajax");
80	
81	        String err = loginResp.jsonPath().getString("err");
82	        if (!"000".equals(err)) {
83	            throw new RuntimeException("Login step 1 failed: err=" + err);
84	        }
85	        long accountSeq = loginResp.jsonPath().getLong("accountSeq");
86	
87	        // SESSION는 1단계에서 발급됨 — 이후 모든 요청에 이 쿠키 사용
88	        String jsessionId = loginResp.getCookie("SESSION");
89	        if (jsessionId == null || jsessionId.isEmpty()) {
90	            throw new RuntimeException("No SESSION cookie from login/ajax");
91	        }
92	
93	        // 2단계: DB에서 인증번호 직접 조회
94	        String certNo;
95	        try (java.sql.PreparedStatement ps = conn.prepareStatement(
96	                "SELECT CERTIFICATION_NO FROM ACCOUNT_SMS WHERE ACCOUNT_SEQ = ?")) {
97	            ps.setLong(1, accountSeq);
98	            java.sql.ResultSet rs = ps.executeQuery();
99	            if (!rs.next()) throw new RuntimeException("No SMS info found for accountSeq=" + accountSeq);
100	            certNo = rs.getString(1);
101	        } catch (Exception e) {
102	            throw new RuntimeException("Failed to read SMS certification", e);
103	        }
104	
105	        // 3단계: SMS 인증 → 세션 생성
106	        io.restassured.response.Response smsResp = io.restassured.RestAssured.given()
107	            .baseUri(baseUrl)
108	            .cookie("SESSION", jsessionId)
109	            .header("X-Requested-With", "XMLHttpRequest")
110	            .contentType("application/x-www-form-urlencoded")
111	            .formParam("id", id)
112	            .formParam("pw", pw)
113	            .formParam("accountSeq", accountSeq)
114	            .formParam("certificationNo", certNo)
115	        .when()
116	            .post("/web/login/sms");
117	
118	        String smsErr = smsResp.jsonPath().getString("err");
119	        if (!"000".equals(smsErr)) {
120	            throw new RuntimeException("Login step 2 (SMS) failed: err=" + smsErr);
121	        }
122	
123	        // 3-B단계: 약관 동의가 필요한 경우 (AUTHZ가 01, 07이 아닌 계정)
124	        String termsJson = smsResp.jsonPath().getString("terms");
125	        if (termsJson != null) {
126	            long mngAgreeTermsSeq = smsResp.jsonPath().getLong("terms.latestTerms.mngAgreeTermsSeq");
127	            int version = smsResp.jsonPath().getInt("terms.latestTerms.version");
128	
129	            io.restassured.response.Response agreeResp = io.restassured.RestAssured.given()
130	                .baseUri(baseUrl)
131	                .cookie("SESSION", jsessionId)
132	                .header("X-Requested-With", "XMLHttpRequest")
133	                .contentType("application/x-www-form-urlencoded")
134	                .formParam("id", id)
135	                .formParam("pw", pw)
136	                .formParam("accountSeq", accountSeq)
137	                .formParam("mngAgreeTermsSeq", mngAgreeTermsSeq)
138	                .formParam("version", version)
139	            .when()
140	                .post("/web/login/agreeTerms");
141	
142	            String agreeErr = agreeResp.jsonPath().getString("err");
143	            if (agreeErr != null && !"000".equals(agreeErr)) {
144	                String agreeErrMsg = agreeResp.jsonPath().getString("errMsg");
145	                // errMsg가 숫자 코드(100, 200 등)이면 정상 로그인 완료
146	                if (agreeErrMsg == null || (!agreeErrMsg.matches("\\d+") && !"success".equalsIgnoreCase(agreeErrMsg))) {
147	                    throw new RuntimeException("Login step 3-B (agreeTerms) failed: err=" + agreeErr + ", errMsg=" + agreeErrMsg);
148	                }
149	            }
150	
151	            // agreeTerms 응답에서 tokenErr 확인
152	            String tokenErr = agreeResp.jsonPath().getString("tokenErr");
153	            if ("001".equals(tokenErr)) {
154	                // 이미 로그인된 세션이 있어 loginToken이 설정되지 않음 → token 발급 요청
155	                io.restassured.RestAssured.given()
156	                    .baseUri(baseUrl)
157	                    .cookie("SESSION", jsessionId)
158	                    .header("X-Requested-With", "XMLHttpRequest")
159	                    .contentType("application/x-www-form-urlencoded")
160	                .when()
161	                    .post("/web/login/token");
162	            }
163	        } else {
164	            // 약관 동의 불필요 — tokenErr 확인
165	            String tokenErr = smsResp.jsonPath().getString("tokenErr");
166	            if ("001".equals(tokenErr)) {
167	                io.restassured.RestAssured.given()
168	                    .baseUri(baseUrl)
169	                    .cookie("SESSION", jsessionId)
170	                    .header("X-Requested-With", "XMLHttpRequest")
171	                    .contentType("application/x-www-form-urlencoded")
172	                .when()
173	                    .post("/web/login/token");
174	            }
175	        }
176	
177	        return jsessionId;
178	    }
