250	    @SuppressWarnings("deprecation")
251	    private static void initKmsIfNeeded() {
252	        if (awsCrypto != null) return;
253	
254	        String endpoint = System.getProperty("test.localstack.endpoint", "http://localhost:4566");
255	        String region = System.getProperty("test.aws.region", "ap-northeast-2");
256	        String keyAlias = "alias/cmk-2-pltelapne2"; // dataEncryptionService용 CMK
257	
258	        awsCrypto = com.amazonaws.encryptionsdk.AwsCrypto.builder()
259	            .withCommitmentPolicy(com.amazonaws.encryptionsdk.CommitmentPolicy.RequireEncryptRequireDecrypt)
260	            .build();
261	
262	        software.amazon.awssdk.services.kms.KmsClient kmsClient =
263	            software.amazon.awssdk.services.kms.KmsClient.builder()
264	                .region(software.amazon.awssdk.regions.Region.of(region))
265	                .endpointOverride(java.net.URI.create(endpoint))
266	                .credentialsProvider(software.amazon.awssdk.auth.credentials.StaticCredentialsProvider.create(
267	                    software.amazon.awssdk.auth.credentials.AwsBasicCredentials.create("test", "test")))
268	                .build();
269	
270	        // alias → ARN 변환
271	        String keyArn = kmsClient.describeKey(
272	            software.amazon.awssdk.services.kms.model.DescribeKeyRequest.builder()
273	                .keyId(keyAlias).build()
274	        ).keyMetadata().arn();
275	
276	        com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider provider =
277	            com.amazonaws.encryptionsdk.kmssdkv2.KmsMasterKeyProvider.builder()
278	                .defaultRegion(software.amazon.awssdk.regions.Region.of(region))
279	                .customRegionalClientSupplier(r -> kmsClient)
280	                .buildStrict(keyArn);
281	
282	        com.amazonaws.encryptionsdk.caching.CryptoMaterialsCache cache =
283	            new com.amazonaws.encryptionsdk.caching.LocalCryptoMaterialsCache(100);
284	        cachingCmm = com.amazonaws.encryptionsdk.caching.CachingCryptoMaterialsManager.newBuilder()
285	            .withMasterKeyProvider(provider)
286	            .withCache(cache)
287	            .withMaxAge(5, java.util.concurrent.TimeUnit.MINUTES)
288	            .withMessageUseLimit(1000)
289	            .build();
290	    }
