292	    /**
293	     * setup SQL 실행 후, 지정된 MEMBER의 CTN을 KMS로 암호화된 값으로 UPDATE한다.
294	     * 동시에 CTN_HASH 컬럼도 HMAC-SHA256 해시로 UPDATE한다.
295	     *
296	     * @param conn DB 연결
297	     * @param memberSeq 대상 MEMBER_SEQ
298	     * @param plainCtn 평문 CTN (예: "01012345678")
299	     */
300	    static void encryptMemberCtn(Connection conn, long memberSeq, String plainCtn) {
301	        String encrypted = kmsEncrypt(plainCtn);
302	        String hash = hmacSha256(plainCtn);
303	        try (java.sql.PreparedStatement ps = conn.prepareStatement(
304	                "UPDATE MEMBER SET CTN = ?, CTN_HASH = ? WHERE MEMBER_SEQ = ?")) {
305	            ps.setString(1, encrypted);
306	            ps.setString(2, hash);
307	            ps.setLong(3, memberSeq);
308	            int updated = ps.executeUpdate();
309	            if (updated == 0) {
310	                throw new RuntimeException("MEMBER not found: MEMBER_SEQ=" + memberSeq);
311	            }
312	        } catch (RuntimeException e) {
313	            throw e;
314	        } catch (Exception e) {
315	            throw new RuntimeException("Failed to encrypt MEMBER CTN", e);
316	        }
317	    }
