447	    /**
448	     * HMAC-SHA256 해시 생성 (서버의 HashUtil.hmacSha256과 동일 로직).
449	     * pepper는 docker-compose.yml의 HASH_PEPPER 환경변수와 동일해야 한다.
450	     */
451	    static String hmacSha256(String plaintext) {
452	        if (plaintext == null || plaintext.isEmpty()) return "";
453	        String pepper = System.getProperty("test.hash.pepper", "test_pepper_value");
454	        try {
455	            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
456	            javax.crypto.spec.SecretKeySpec keySpec = new javax.crypto.spec.SecretKeySpec(
457	                    pepper.getBytes(java.nio.charset.StandardCharsets.UTF_8), "HmacSHA256");
458	            mac.init(keySpec);
459	            byte[] hash = mac.doFinal(plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8));
460	            StringBuilder sb = new StringBuilder(hash.length * 2);
461	            for (byte b : hash) sb.append(String.format("%02x", b));
