	})
	@RequestMapping(value = "/sync", method = RequestMethod.GET)
	public String sync(@RequestParamMap ParamMap param,
					   @RequestHeader(value = "X-Manufacturer", required = true) String manufacturer,
					   @RequestHeader(value = "X-Model", required = true) String deviceModel,
					   @RequestHeader(value = "X-OS-Version", required = true) String osVersion,
					   @RequestHeader(value = "X-App-Version", required = true) String appVersion,
					   @RequestHeader(value = "Authorization", required = true) String authorization,
					   HttpServletRequest request, Model model) throws LogicException {
		LogInfo logInfo = setDeviceLog(param, "S02");
		try {
			param.put("authorization", authorization);
			model.addAllAttributes(service.sync(param, request));
			logInfo.setRESULT_CODE("000");
