        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-setup.sql", AdminEcgiBlackBoxTest.class);
        // ECGI 컬럼을 LocalStack KMS(CMK-1)로 암호화 — 서버가 응답 시 decrypt하므로 필수
