        sessionId = TestUtil.adminLogin(BASE_URL, "ecgiadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-ecgi-teardown.sql", AdminEcgiBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

