    @Test @Order(1)
    void NTC_ecgiList() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .queryParam("length", 10).queryParam("start", 0)
        .when().get("/web/admin/ecgis/ajax")
        .then().log().all().statusCode(200)
            .body("iTotalRecords", equalTo(1))
            .body("aaData[0].ecgi", equalTo("1234567890"))
            .body("aaData[0].name", equalTo("TestEcgi"))
            .body("aaData[0].location", equalTo("TestLocation"));
    }

    // ==================== POST / — ECGI 등록 (403 Forbidden for AUTHZ='02') ====================

