	public ClientResultMap sync(ParamMap param, HttpServletRequest request) {
		ClientResultMap result = new ClientResultMap();
		int loggerStep = 0;

		try {
			long memberSeq = (long) request.getSession().getAttribute("memberSeq");
			long clientSeq = (long) request.getSession().getAttribute("clientSeq");
			param.put("memberSeq", memberSeq);
			param.put("clientSeq", clientSeq);

			logger.info("[STEP{}] - Start sync", ++loggerStep);
			Map<String, Object> data = new java.util.HashMap<>();

			// 최신 약관 버전
			logger.info("[STEP{}] - Get latest terms version", ++loggerStep);
			Map<String, Object> termsVersion = dao.getLatestTermsVersion();
			data.put("latestTermsVersion", termsVersion != null ? termsVersion.get("latestTermsVersion") : null);

			// 최신 공지 버전
			logger.info("[STEP{}] - Get latest notice version", ++loggerStep);
			Map<String, Object> noticeVersion = dao.getLatestNoticeVersion();
			data.put("latestNoticeVersion", noticeVersion != null ? noticeVersion.get("latestNoticeVersion") : null);

			// 고객사 기본 정보 (배경이미지 + 연동앱 버전)
			logger.info("[STEP{}] - Get client sync info", ++loggerStep);
			Map<String, Object> clientSyncInfo = dao.getClientSyncInfo(param);
			data.put("mainBackgroundImageUrl", clientSyncInfo != null ? clientSyncInfo.get("mainBackgroundImageUrl") : null);
			data.put("interlockingAppVersion", clientSyncInfo != null ? clientSyncInfo.get("interlockingAppVersion") : null);

			// 연동앱 목록
			logger.info("[STEP{}] - Get interlocking app list", ++loggerStep);
			data.put("interlockingAppList", dao.getInterlockingAppList(param));

			// 허용 ECGI 목록 (복호화)
			logger.info("[STEP{}] - Get allowed ECGI list and decrypt", ++loggerStep);
			List<String> encryptedEcgiList = dao.getAllowedEcgiList(param);
			List<String> decryptedEcgiList = kmsUtil.simpleDataCryptoList(encryptedEcgiList, false);
			data.put("allowedEcgiList", decryptedEcgiList);
			logger.info("[STEP{}] - Decrypted ECGI list size: {}", ++loggerStep, decryptedEcgiList != null ? decryptedEcgiList.size() : 0);

			// 솔루션 목록
			logger.info("[STEP{}] - Get solution list", ++loggerStep);
			List<HashMap<String, Object>> solutionList = dao.getSolutionList(param);
			solutionList.forEach(s -> s.put("enabled", Integer.valueOf(1).equals(s.get("enabled"))));
			data.put("solutionList", solutionList);
			logger.info("[STEP{}] - Solution list size: {}", ++loggerStep, solutionList.size());

			result.setData(data);
			logger.info("[STEP{}] - Sync completed successfully", ++loggerStep);
		} catch (LogicException le) {
			logger.error("[sync] LogicException: code={}, message={}", le.getCode(), le.getMessage());
			result.setCode(le.getCode());
			result.setMessage(le.getMessage());
		} catch (Exception e) {
			logger.error("[sync] Exception: {}", e.getMessage());
			result.setCode(Constants.UNKNOWN_ERR_CODE);
			result.setMessage(e.getMessage());
		}

		return result;
	}

