1	package com.ahope.ds.common.interceptor;
2	
3	import java.time.LocalDateTime;
4	import java.time.format.DateTimeFormatter;
5	import java.util.Locale;
6	import java.util.Map;
7	import java.util.regex.Pattern;
8	
9	import jakarta.servlet.http.HttpServletRequest;
10	import jakarta.servlet.http.HttpServletResponse;
11	import jakarta.servlet.http.HttpSession;
12	
13	import org.slf4j.Logger;
14	import org.slf4j.LoggerFactory;
15	import org.slf4j.MDC;
16	import org.springframework.beans.factory.annotation.Autowired;
17	import org.springframework.beans.factory.annotation.Qualifier;
18	import org.springframework.stereotype.Component;
19	import org.springframework.web.method.HandlerMethod;
20	import org.springframework.web.servlet.HandlerInterceptor;
21	import org.springframework.web.servlet.ModelAndView;
22	import org.springframework.web.servlet.i18n.SessionLocaleResolver;
23	
24	import com.ahope.ds.common.aws.kms.AwsKmsEncryptionService;
25	import com.ahope.ds.common.bean.LogInfo;
26	import com.ahope.ds.common.constnats.Constants;
27	import com.ahope.ds.common.exception.LogicException;
28	import com.ahope.ds.common.extension.annotation.NoAuth;
29	import com.ahope.ds.common.util.CommonUtil;
30	import com.fasterxml.jackson.databind.ObjectMapper;
31	
32	@Component
33	public class ClientLoginInterceptor implements HandlerInterceptor {
34	
35		protected Logger logger = LoggerFactory.getLogger(ClientLoginInterceptor.class);
36		protected Logger lgLogger = LoggerFactory.getLogger("lgLogger");
37	
38		private static final DateTimeFormatter TOKEN_DATE_FORMAT = DateTimeFormatter.ofPattern("yyyyMMddHHmmss");
39	
40		@Autowired
41		@Qualifier("tokenEncryptionService")
42		private AwsKmsEncryptionService tokenEncryptionService;
43	
44		@Autowired
45		private SessionLocaleResolver localeResolver;
46	
47		@SuppressWarnings("unchecked")
48		@Override
49		public boolean preHandle(HttpServletRequest req, HttpServletResponse res, Object handler) throws Exception {
50	
51			MDC.put("RID", CommonUtil.getRandomStr());
52	
53			HttpSession session = req.getSession();
54	
55			session.setAttribute("osInfo", CommonUtil.nvl(req.getHeader("X-OS-Version")));
56			session.setAttribute("networkInfo", CommonUtil.nvl(req.getHeader("networkInfo")));
57			session.setAttribute("deviceModel", CommonUtil.nvl(req.getHeader("X-Model")));
58			session.setAttribute("deviceInfo", CommonUtil.nvl(req.getHeader("X-Manufacturer")));
59	
60			logger.info("[ LOCALE ] " + req.getHeader("lang"));
61			String localeStr = Constants.LOCALE_KOREAN;
62			if (!CommonUtil.isNull(req.getHeader("lang"))) {
63				localeStr = req.getHeader("lang");
64				if (!localeStr.equals(Constants.LOCALE_ENGLISH)
65						&& !localeStr.equals(Constants.LOCALE_CHINESE)
66						&& !localeStr.equals(Constants.LOCALE_VIETNAMESE)) {
67					localeStr = Constants.LOCALE_KOREAN;
68				}
69			}
70			Locale locale = new Locale(localeStr);
71			localeResolver.setLocale(req, res, locale);
72			session.setAttribute("lang", locale);
73	
74			if (handler instanceof HandlerMethod) {
75				HandlerMethod handlerMethod = (HandlerMethod) handler;
76				if (handlerMethod.hasMethodAnnotation(NoAuth.class)) {
77					return true;
78				}
79			}
80	
81			// 통합 로그용 LogInfo 생성
82			LogInfo logInfo = new LogInfo(
83					"SVC"
84					, CommonUtil.nvl(req.getRemoteAddr())
85					, (String) session.getAttribute("deviceInfo")
86					, CommonUtil.nvl(req.getHeader("X-OS-Version"))
87					, (String) session.getAttribute("networkInfo")
88					, ""
89					, CommonUtil.nvl(req.getHeader("X-Model"))
90					, "1"
91					, ""
92					, ""
93					, ""
94					, ""
95					, ""
96					, ""
97					, "");
98	
99			String authorization = req.getHeader("Authorization");
100	
101			if (CommonUtil.isNull(authorization)) {
102				logInfo = getServiceCode(req.getRequestURI(), logInfo);
103				logInfo.setRESULT_CODE(Constants.MISSING_TOKEN_VALUE_CODE);
104				lgLogger.info(logInfo.toString());
105				throw new LogicException(Constants.MISSING_TOKEN_VALUE_MSG, Constants.MISSING_TOKEN_VALUE_CODE);
106			}
107	
108			if (!authorization.startsWith("Bearer ")) {
109				logInfo = getServiceCode(req.getRequestURI(), logInfo);
110				logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_CODE);
111				lgLogger.info(logInfo.toString());
112				throw new LogicException(Constants.INVALID_TOKEN_MSG, Constants.INVALID_TOKEN_CODE);
113			}
114	
115			String accessToken = authorization.substring("Bearer ".length()).trim();
116			String decrypted;
117	
118			try {
119				decrypted = tokenEncryptionService.decrypt(accessToken);
120				logger.info("복호화 토큰(임시): " + decrypted); // TODO DELETE HW
121			} catch (Exception e) {
122				logger.error("[ClientLoginInterceptor] Token decryption failed", e);
123				logInfo = getServiceCode(req.getRequestURI(), logInfo);
124				logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_CODE);
125				lgLogger.info(logInfo.toString());
126				throw new LogicException(Constants.INVALID_TOKEN_MSG, Constants.INVALID_TOKEN_CODE);
127			}
128	
129			ObjectMapper objectMapper = new ObjectMapper();
130			Map<String, Object> tokenPayload = objectMapper.readValue(decrypted, Map.class);
131	
132			String tokenType = (String) tokenPayload.get("tokenType");
133			if (!Constants.TOKEN_TYPE_ACCESS.equals(tokenType)) {
134				logInfo = getServiceCode(req.getRequestURI(), logInfo);
135				logInfo.setRESULT_CODE(Constants.INVALID_TOKEN_TYPE_CODE);
136				lgLogger.info(logInfo.toString());
137				throw new LogicException(Constants.INVALID_TOKEN_TYPE_MSG, Constants.INVALID_TOKEN_TYPE_CODE);
138			}
139	
140			String expiredAt = (String) tokenPayload.get("expiredAt");
141			String now = LocalDateTime.now().format(TOKEN_DATE_FORMAT);
142			if (now.compareTo(expiredAt) > 0) {
143				logInfo = getServiceCode(req.getRequestURI(), logInfo);
144				logInfo.setRESULT_CODE(Constants.TOKEN_EXPIRED_CODE);
145				lgLogger.info(logInfo.toString());
146				throw new LogicException(Constants.TOKEN_EXPIRED_MSG, Constants.TOKEN_EXPIRED_CODE);
147			}
148	
149			// memberSeq, clientSeq 세션 설정
150			long memberSeq = ((Number) tokenPayload.get("memberSeq")).longValue();
151			long clientSeq = ((Number) tokenPayload.get("clientSeq")).longValue();
152			session.setAttribute("memberSeq", memberSeq);
153			session.setAttribute("clientSeq", clientSeq);
154	
155			return true;
156		}
157	
158		@Override
159		public void postHandle(HttpServletRequest req, HttpServletResponse res, Object handler, ModelAndView mnv) throws Exception {
160			logger.info("[ClientLoginInterceptor] postHandle");
161		}
162	
163		@Override
164		public void afterCompletion(HttpServletRequest req, HttpServletResponse res, Object handler, Exception e) throws Exception {
165			logger.info("[ClientLoginInterceptor] afterCompletion");
166		}
167	
168		private LogInfo getServiceCode(String requestURI, LogInfo logInfo) {
169			String serviceClass = "";
170			String legacyClass = "";
171			if (Pattern.matches("^(\\/client\\/checklist).*", requestURI)) {
172				serviceClass = "S01";
173			} else if (Pattern.matches("^(\\/client\\/version).*", requestURI)) {
174				serviceClass = "S02";
175			} else if (Pattern.matches("^(\\/client\\/init).*", requestURI)) {
176				serviceClass = "S03";
177			} else if (Pattern.matches("^(\\/client\\/sync).*", requestURI)) {
178				serviceClass = "S04";
179			} else if (Pattern.matches("^(\\/client\\/terms).*", requestURI)) {
180				serviceClass = "S05";
181			} else if (Pattern.matches("^(\\/client\\/auth).*", requestURI)) {
182				serviceClass = "S06";
183			} else if (Pattern.matches("^(\\/client\\/notice).*", requestURI)) {
184				serviceClass = "S07";
