 * 페이로드: {"tokenType":"ACCESS","expiredAt":"20991231235959","memberSeq":..,"clientSeq":..}
 *
 * @param memberSeq 세션에 설정될 가입자 시퀀스
 * @param clientSeq 세션에 설정될 고객사 시퀀스
 * @return Bearer 뒤에 붙일 암호화된 ACCESS 토큰
 */
static String clientAccessToken(long memberSeq, long clientSeq) {
    String payload = "{\"tokenType\":\"ACCESS\",\"expiredAt\":\"20991231235959\","
            + "\"memberSeq\":" + memberSeq + ",\"clientSeq\":" + clientSeq + "}";
    return kmsEncryptToken(payload);
}

