package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientAPIController (src/main/java/com/ahope/ds/client/controller/ClientAPIController.java)
 * @target-api GET /client/sync
 *
 * 인증: ClientLoginInterceptor (/client/**) — Authorization: Bearer <ACCESS_TOKEN>
 *   토큰은 tokenEncryptionService(CMK-4)로 암호화된 JSON
 *   {"tokenType":"ACCESS","expiredAt":"yyyyMMddHHmmss","memberSeq":..,"clientSeq":..}.
 *   인터셉터가 복호화 후 memberSeq/clientSeq를 세션에 설정하고 handler로 진행한다.
 * 외부 연동: LocalStack KMS(토큰/데이터 복호화)만 사용 — 외부 HTTP 호출 없음 → WireMock 불필요.
 * DB 의존: CLIENT, MEMBER, TERMS/NOTICE 버전, ECGI, SOLUTION, INTERLOCKING_APP (조회, null 허용).
 *
 * NTC는 응답 envelope(code/message)을 검증한다. sync 서비스는 예외 시에만 에러코드를 세팅하고,
 * 데이터가 없어도 code=200/message=OK로 응답한다 (ClientResultMap 기본값).
 */
class ClientSyncBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;

    private static final long MEMBER_SEQ = 90091L;
    private static final long CLIENT_SEQ = 97091L;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/client-sync-setup.sql", ClientSyncBlackBoxTest.class);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/client-sync-teardown.sql", ClientSyncBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC ====================

    /** [NTC_sync_success] 유효한 ACCESS 토큰 → code=200, message=OK */
    @Test
    void NTC_sync_success() {
        String token = TestUtil.clientAccessToken(MEMBER_SEQ, CLIENT_SEQ);
        given().log().all().baseUri(BASE_URL)
            .header("Authorization", "Bearer " + token)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"))
            .body("message", equalTo("OK"));
    }

    /** [NTC_sync_success_otherClient] 다른 고객사 토큰 → code=200 */
    @Test
    void NTC_sync_success_otherClient() {
        String token = TestUtil.clientAccessToken(MEMBER_SEQ, CLIENT_SEQ);
        given().log().all().baseUri(BASE_URL)
            .header("Authorization", "Bearer " + token)
            .header("X-Manufacturer", "LGE")
            .header("X-Model", "LM-V510N")
            .header("X-OS-Version", "12")
            .header("X-App-Version", "01.05.00")
        .when().get("/client/sync")
        .then().log().all().statusCode(200)
            .body("code", equalTo("200"));
    }

    // ==================== VTC (인터셉터 토큰 검증) ====================

    /**
     * [VTC_authorization_NULL] Authorization 헤더 누락
     * ClientLoginInterceptor가 LogicException(MISSING_TOKEN_VALUE,816)을 던진다.
     * 컨트롤러 로컬 @ExceptionHandler는 인터셉터 예외를 잡지 못하므로 서블릿 기본 처리(500)로 응답한다.
     */
    @Test
    void VTC_authorization_NULL() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
        .when().get("/client/sync")
        .then().log().all().statusCode(500);
    }

    /**
     * [VTC_authorization_INVALID_FORMAT] Bearer 접두사 없는 토큰 → INVALID_TOKEN(812) → 500
     */
    @Test
    void VTC_authorization_INVALID_FORMAT() {
        given().log().all().baseUri(BASE_URL)
            .header("Authorization", "not-a-bearer-token")
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
        .when().get("/client/sync")
        .then().log().all().statusCode(500);
    }

    /**
     * [VTC_accessToken_UNDECRYPTABLE] Bearer + 복호화 불가 토큰 → INVALID_TOKEN(812) → 500
     */
    @Test
    void VTC_accessToken_UNDECRYPTABLE() {
        given().log().all().baseUri(BASE_URL)
            .header("Authorization", "Bearer AAAAABBBBBCCCCC-garbage")
            .header("X-Manufacturer", "samsung")
            .header("X-Model", "SM-G998N")
            .header("X-OS-Version", "14")
            .header("X-App-Version", "02.00.01")
        .when().get("/client/sync")
        .then().log().all().statusCode(500);
    }
}

