package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller ClientController (src/main/java/com/ahope/ds/web/superadmin/client/controller/ClientController.java)
 * @target-api PUT /web/super/admin/clients/{clientSeq}/cancel
 *
 * 인증: SuperAdminLoginInterceptor (/web/super/admin/**) — 슈퍼관리자(AUTHZ=07) 세션.
 * 외부 연동: 없음 (DB 처리만) → WireMock 불필요.
 * DB 의존: CLIENT (CANCEL_STATUS), CLIENT_MANAGER, MEMBER, LPS 조회.
 *   가입(01) 상태 고객사를 해지요청(02)으로 전환한다.
 */
class SuperadminClientCancelBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    private static final long CLIENT_SEQ = 97010L; // admin-client-list-setup: CANCEL_STATUS='01'

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        sessionId = TestUtil.adminLogin(BASE_URL, "clientadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-client-list-teardown.sql", SuperadminClientCancelBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    @BeforeEach
    void resetData() {
        // 방어적 teardown → setup (멱등성 보장) — CANCEL_STATUS를 매번 '01'로 초기화
        TestUtil.executeSql(dbConnection, "sql/admin-client-list-teardown.sql", SuperadminClientCancelBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-client-list-setup.sql", SuperadminClientCancelBlackBoxTest.class);
    }

    // ==================== NTC ====================

    /** [NTC_cancelClient] 가입(01) 고객사 해지 요청 → err=000, CANCEL_STATUS='02' */
    @Test
    void NTC_cancelClient() throws Exception {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
        .when().put("/web/super/admin/clients/" + CLIENT_SEQ + "/cancel")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));

        try (PreparedStatement ps = dbConnection.prepareStatement(
                "SELECT CANCEL_STATUS FROM CLIENT WHERE CLIENT_SEQ = ?")) {
            ps.setLong(1, CLIENT_SEQ);
            ResultSet rs = ps.executeQuery();
            assertTrue(rs.next());
            assertEquals("02", rs.getString("CANCEL_STATUS"));
        }
    }

    // ==================== VTC ====================

    /** [VTC_clientSeq_INVALID_FORMAT] path variable가 숫자가 아니면 Spring이 400 반환 */
    @Test
    void VTC_clientSeq_INVALID_FORMAT() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/not-a-number/cancel")
        .then().log().all().statusCode(400);
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 호출 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
        .when().put("/web/super/admin/clients/" + CLIENT_SEQ + "/cancel")
        .then().log().all().statusCode(401);
    }
}

