 */
class SuperadminCryptoPersonalBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    private static final String PLAIN = "01099998888";

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-account-list-teardown.sql", SuperadminCryptoPersonalBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-account-list-setup.sql", SuperadminCryptoPersonalBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "accadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-account-list-teardown.sql", SuperadminCryptoPersonalBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC ====================

    /** [NTC_decrypt_personal] CMK-2로 암호화된 값 복호화 → err=000, 평문 반환 */
    @Test
    void NTC_decrypt_personal() {
        String cipher = TestUtil.kmsEncrypt(PLAIN);
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(PLAIN));
    }

    /** [NTC_decrypt_personal_email] 다른 평문(이메일) 복호화 → err=000, 평문 반환 */
    @Test
    void NTC_decrypt_personal_email() {
        String plain = "tester@example.com";
        String cipher = TestUtil.kmsEncrypt(plain);
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", cipher)
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"))
            .body("cryptoResult", equalTo(plain));
    }

    // ==================== VTC ====================

    /** [VTC_cryptoContent_INVALID_FORMAT] 복호화 불가한 암호문 → err=115 */
    @Test
    void VTC_cryptoContent_INVALID_FORMAT() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "not-a-valid-ciphertext")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(200)
            .body("err", equalTo("115"));
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 호출 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("cryptoContent", "anything")
        .when().post("/web/super/admin/crypto/personal")
        .then().log().all().statusCode(401);
    }
}

