/**
 * Black-Box API Integration Test
 *
 * @target-controller HistoryController (src/main/java/com/ahope/ds/web/superadmin/history/controller/HistoryController.java)
 * @target-api POST /web/super/admin/history/sync/cancel/excel/make
 *
 * 인증: SuperAdminLoginInterceptor (/web/super/admin/**) — 슈퍼관리자(AUTHZ=07) 세션.
 * 외부 연동: 없음 (엑셀 생성 요청 → 서버 내부 처리) → WireMock 불필요.
 * 핸들러: excelReason에 취약 문자열 포함 시 LogicException(VULNERABLE_VALUE, 002).
 */
class SuperadminHistorySyncCancelExcelBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    private static final String START_DATE = "2026-01-01";
    private static final String END_DATE = "2026-12-31";

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-history-teardown.sql", SuperadminHistorySyncCancelExcelBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-history-setup.sql", SuperadminHistorySyncCancelExcelBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "historyadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-history-teardown.sql", SuperadminHistorySyncCancelExcelBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== NTC ====================

    /** [NTC_makeExcel_nameSearch] 이름 검색 조건으로 엑셀 생성 요청 → err=000 */
    @Test
    void NTC_makeExcel_nameSearch() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchType", "NAME")
            .formParam("searchValue", "")
            .formParam("searchStartDate", START_DATE)
            .formParam("searchEndDate", END_DATE)
            .formParam("excelReason", "해지 동기화 이력 다운로드")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    /** [NTC_makeExcel_ctnSearch] CTN 검색 조건으로 엑셀 생성 요청 → err=000 */
    @Test
    void NTC_makeExcel_ctnSearch() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchType", "CTN")
            .formParam("searchValue", "")
            .formParam("searchStartDate", START_DATE)
            .formParam("searchEndDate", END_DATE)
            .formParam("excelReason", "업무용")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("000"));
    }

    // ==================== VTC ====================

    /** [VTC_excelReason_SPECIAL_CHAR] excelReason XSS 문자열 → VULNERABLE_VALUE(002) */
    @Test
    void VTC_excelReason_SPECIAL_CHAR() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchType", "NAME")
            .formParam("searchValue", "")
            .formParam("searchStartDate", START_DATE)
            .formParam("searchEndDate", END_DATE)
            .formParam("excelReason", "<script>alert('xss')</script>")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().log().all().statusCode(200)
            .body("err", equalTo("002"));
    }

    // ==================== ATC ====================

    /** [ATC_noSession] 세션 없이 호출 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchType", "NAME")
            .formParam("searchStartDate", START_DATE)
            .formParam("searchEndDate", END_DATE)
            .formParam("excelReason", "업무용")
        .when().post("/web/super/admin/history/sync/cancel/excel/make")
        .then().log().all().statusCode(401);
    }
}

