package com.ahope.ds.blackbox;

import static io.restassured.RestAssured.given;

import java.sql.Connection;
import java.sql.DriverManager;

import org.junit.jupiter.api.AfterAll;
import org.junit.jupiter.api.BeforeAll;
import org.junit.jupiter.api.Test;

/**
 * Black-Box API Integration Test
 *
 * @target-controller TrafficController (src/main/java/com/ahope/ds/web/admin/traffic/controller/TrafficController.java)
 * @target-api POST /web/admin/traffic/excel/make
 *
 * 인증: AdminLoginInterceptor (/web/admin/**).
 *   NOTE: /web/admin/traffic/excel/make 는 시스템/슈퍼 관리자만 접근 가능한
 *   AdminLoginInterceptor 블랙리스트 경로이다. 테스트 계정 trafficadmin(AUTHZ='02')로는
 *   핸들러에 도달하기 전에 403이 반환된다. 따라서 정상 흐름(err=000) 및 excelReason
 *   취약성 분기(VULNERABLE_VALUE, 002)는 이 계정으로 검증 불가하며, 모두 403으로 차단된다.
 *   (핸들러 로직 자체의 커버리지는 시스템 관리자 계정 + 트래픽 데이터가 필요하다.)
 * 외부 연동: 없음 → WireMock 불필요.
 */
class AdminTrafficExcelMakeBlackBoxTest {

    private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");
    private static Connection dbConnection;
    private static String sessionId;

    @BeforeAll
    static void setUp() throws Exception {
        dbConnection = DriverManager.getConnection(
            System.getProperty("test.db.url", "jdbc:mariadb://localhost:13306/smart_plant"),
            System.getProperty("test.db.user", "smartplant"),
            System.getProperty("test.db.password", "smartplant1234"));
        TestUtil.executeSql(dbConnection, "sql/admin-traffic-teardown.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        TestUtil.executeSql(dbConnection, "sql/admin-traffic-setup.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        sessionId = TestUtil.adminLogin(BASE_URL, "trafficadmin", "testpw", dbConnection);
    }

    @AfterAll
    static void cleanup() throws Exception {
        TestUtil.executeSql(dbConnection, "sql/admin-traffic-teardown.sql", AdminTrafficExcelMakeBlackBoxTest.class);
        if (dbConnection != null) dbConnection.close();
    }

    // ==================== ATC (권한 차단) ====================

    /** [ATC_makeExcel_calculate_forbidden] 정산 엑셀 생성 요청 — AUTHZ=02 → 403 */
    @Test
    void ATC_makeExcel_calculate_forbidden() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "업무용 테스트")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(403);
    }

    /** [ATC_makeExcel_realtime_forbidden] 실시간 엑셀 생성 요청 — AUTHZ=02 → 403 */
    @Test
    void ATC_makeExcel_realtime_forbidden() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchDataType", "REAL_TIME")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "업무용 테스트")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(403);
    }

    // ==================== VTC ====================

    /**
     * [VTC_excelReason_SPECIAL_CHAR] excelReason XSS 문자열.
     * 핸들러의 취약성 분기(002)에 도달하기 전에 인터셉터 블랙리스트가 403으로 차단한다.
     */
    @Test
    void VTC_excelReason_SPECIAL_CHAR_forbidden() {
        given().log().all().baseUri(BASE_URL)
            .cookie("SESSION", sessionId)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchPeriodType", "SEARCH_FOR_MONTH")
            .formParam("searchTrafficType", "TOTAL")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "<script>alert('xss')</script>")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(403);
    }

    // ==================== ATC (세션) ====================

    /** [ATC_noSession] 세션 없이 호출 → 401 */
    @Test
    void ATC_noSession() {
        given().log().all().baseUri(BASE_URL)
            .header("X-Requested-With", "XMLHttpRequest")
            .contentType("application/x-www-form-urlencoded")
            .formParam("searchDataType", "CALCULATE")
            .formParam("searchStartDate", "20260301")
            .formParam("searchEndDate", "20260331")
            .formParam("excelReason", "업무용")
        .when().post("/web/admin/traffic/excel/make")
        .then().log().all().statusCode(401);
    }
}
